/bin/zsh -c "python3 -c 'import urllib.request, concurrent.futures
urls=[
\"https://personal.science.psu.edu/rcv4/personal/Publications/vrsqapt.pdf\",
\"https://personal.science.psu.edu/rcv4/personal/Publications/vrsqap.pdf\",
\"https://www.ams.org/journals/bull/1949-55-10/S0002-9904-1949-09313-8/S0002-9904-1949-09313-8.pdf\",
\"https://projecteuclid.org/journals/michigan-mathematical-journal/volume-17/issue-1/Primes-in-arithmetic-progressions/10.1307/mmj/1029000373.pdf\"]
def check(u):
 try:
  with urllib.request.urlopen(u,timeout=20) as r:
   b=r.read()
   return (u,r.status,r.headers.get(\"Content-Type\"),len(b),b[:5].decode(errors=\"replace\"))
 except Exception as e: return (u,str(e))
for x in concurrent.futures.ThreadPoolExecutor(max_workers=4).map(check,urls): print(x)
'"

